#pragma once

/// @file esprom.h
/// @brief The VDAC4 ESP HLE "ROM": the libc / libm / libgcc code the board's firmware exports to app ELFs.
///
/// esprom.cpp is generated by tools/vdac4/esp-rom/build.sh from the Espressif toolchain's esp32s3 newlib, libm
/// and libgcc, linked at kEspRomBase. The interpreter runs it as guest code, so string, printf, math, soft-float
/// and setjmp / longjmp behave as on the board. What the toolchain does not provide (heap_caps, pthread, usleep),
/// newlib's system calls, __getreent and the malloc family (the firmware's heap_caps) are traps at
/// kEspTrapBase + 4 * index (kEspRomTraps), served by the host.
///
/// Design: docs/inprogress/2026-11-15-tsconf-vdac4/design.md §8.4.

#include <cstddef>
#include <cstdint>

namespace vdac4
{

struct EspRomSymbol
{
    const char* name;
    uint32_t address;
};

extern const uint32_t kEspRomBase;
/// Bytes from kEspRomBase the ROM occupies, .bss included (map this much, RW)
extern const uint32_t kEspRomSize;
/// Bytes of kEspRomImage (.text, .rodata, .data); the rest up to kEspRomSize is zero
extern const uint32_t kEspRomImageSize;
extern const uint8_t kEspRomImage[];
extern const uint32_t kEspTrapBase;
/// newlib's struct _reent the ROM's code uses; __getreent returns it
extern const uint32_t kEspRomImpureData;

extern const EspRomSymbol kEspRomTraps[];
extern const size_t kEspRomTrapCount;
extern const EspRomSymbol kEspRomExports[];
extern const size_t kEspRomExportCount;

}  // namespace vdac4
